mapper.select:
SELECT S. ID, S.PERSON_NAME, S.PERSON_ID, S.AREA_NAME, S.EVENT_TYPE, S.SNAP_TIME, S.SNAP_PHOTO_ID, P.PARK_NAME, S.CREATE_TIME, S.FACE_TEMPERATURE, S.DEVICE_ID, dev.DEVICE_NAME FROM SMT_SNAP_PERSON S INNER JOIN SMT_PARK P ON S.PARK_ID=P.ID LEFT JOIN SMT_DEVICE dev ON S.DEVICE_ID=dev.ID
s.PERSON_TYPE = 2
AND S.PERSON_NAME LIKE CONCAT(CONCAT('%',#{query.personName}),'%')
AND S.AREA_ID=#{query.areaId}
AND S.EVENT_TYPE=#{query.eventType}
AND S.PARK_ID=#{query.parkId}
AND S.COMPANY LIKE CONCAT(CONCAT('%',#{query.company}),'%')
AND S.DEVICE_ID =#{query.deviceId}
AND S.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND S.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
AND (dev.THERMAL_ENABLE=0 or dev.THERMAL_ENABLE is null or S.FACE_TEMPERATURE is null or S.FACE_TEMPERATURE <= dev.THERMAL_THRESHOLD)
AND (dev.THERMAL_ENABLE=1 and dev.THERMAL_ENABLE is not null and S.FACE_TEMPERATURE is not null and S.FACE_TEMPERATURE > dev.THERMAL_THRESHOLD)
and S.PARK_ID in
#{item}
ORDER BY s.snap_time DESC

SELECT S. ID, S.PERSON_NAME, ST.COMP_NAME, ST.DEP_NAME, ST.JOB_NAME, ST.JCHE_NAME, ST.BADGE, S.AREA_NAME, S.EVENT_TYPE, S.SNAP_TIME, S.SNAP_PHOTO_ID, P.PARK_NAME, S.CREATE_TIME, S.FACE_TEMPERATURE, S.DEVICE_ID, dev.DEVICE_NAME FROM SMT_SNAP_PERSON S LEFT JOIN SMT_STAFF ST ON S.PERSON_ID = ST. ID INNER JOIN SMT_PARK P ON S.PARK_ID=P.ID LEFT JOIN SMT_DEVICE dev ON S.DEVICE_ID=dev.ID
S.PERSON_TYPE = 1
AND S.PERSON_NAME LIKE CONCAT(CONCAT('%',#{query.personName}),'%')
AND S.AREA_ID=#{query.areaId}
AND ST.BADGE LIKE CONCAT(CONCAT('%',#{query.badge}),'%')
AND S.EVENT_TYPE=#{query.eventType}
AND S.PARK_ID=#{query.parkId}
AND ST.COMP_ID =#{query.compId}
AND ST.DEP_ID =#{query.depId}
AND ST.JOB_ID =#{query.jobId}
AND ST.JOB_NAME LIKE CONCAT(CONCAT('%',#{query.jobName}),'%')
AND ST.JCHE_ID =#{query.jcheId}
AND S.DEVICE_ID =#{query.deviceId}
AND S.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND S.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
AND (dev.THERMAL_ENABLE=0 or dev.THERMAL_ENABLE is null or S.FACE_TEMPERATURE is null or S.FACE_TEMPERATURE <= dev.THERMAL_THRESHOLD)
AND (dev.THERMAL_ENABLE=1 and dev.THERMAL_ENABLE is not null and S.FACE_TEMPERATURE is not null and S.FACE_TEMPERATURE > dev.THERMAL_THRESHOLD)
and S.PARK_ID in
#{item}
ORDER BY S.SNAP_TIME DESC

SELECT s.PERSON_ID, s.SNAP_TIME, s.SNAP_PHOTO_ID, s.AREA_NAME, s.PARK_ID FROM SMT_SNAP_PERSON s
s.PERSON_TYPE=#{query.personType}
AND s.EVENT_TYPE=#{query.eventType}
AND s.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND s.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
ORDER BY s.SNAP_TIME DESC
